  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 The Communication Process and Why Speaking Matters$j$, $j${"readings": [{"title": "Proverbs 18 (King James Version)", "url": "/portal/bible/Proverbs/18"}], "body": "Communication is the sharing of meaning between people. Proverbs 18:21 says, Death and life are in the power of the tongue: and they that love it shall eat the fruit thereof. Words can build up or tear down, and a person who learns to speak well gains a tool for school, work, family and ministry. Proverbs 25:11 adds, A word fitly spoken is like apples of gold in pictures of silver.\n\nEvery act of communication has parts. The sender is the person who has a message. The message is the idea, along with the words, tone and gestures that carry it. The channel is the way the message travels, such as a voice in a room, a phone call, a letter, a video or a text message. The receiver is the person who takes in the message and gives meaning to it. Feedback is the response the receiver sends back, such as a nod, a question or a reply. Noise is anything that blocks or distorts the message. External noise includes a loud room or a bad microphone. Internal noise includes worry, hunger or a distracting thought. Context is the setting and situation in which communication happens.\n\nCommunication can be verbal, meaning it uses words, or nonverbal, meaning it uses tone, face, posture and gestures. Most of the time the two work together. If a speaker says I am glad to be here with a flat voice and a frown, listeners will doubt the words. Communication also comes in several forms. Intrapersonal communication is the talk you hold with yourself. Interpersonal communication takes place between two people. Small group communication happens in teams and committees. Public speaking is one speaker addressing an audience. Mass communication reaches large audiences through media.\n\nSpeaking skills matter in almost every career. Employers regularly rank communication near the top of the skills they want, and a person who can explain an idea clearly, lead a meeting or answer questions with calm is trusted with more. In ministry, Romans 10:14 asks, And how shall they hear without a preacher? The ability to speak well is a gift to be developed with care and humility.\n\nYour task: (1) Name the parts of the communication process and define each. (2) Give an example of external noise and internal noise. (3) Explain why Proverbs 18:21 matters for a speaker.\n\nFlorida standards: Florida speech and communication course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida speech and communication course standards", "script": "Welcome back. Listen, Proverbs 18:21 says, Death and life are in the power of the tongue: and they that love it shall eat the fruit thereof. Words can build up or tear down, and a person who speaks well has a tool for school, work, family and ministry.\n\nNow watch this. Communication is the sharing of meaning. The sender has a message. The message is carried by words, tone and gestures. The channel is how it travels, like a voice, a phone or a letter. The receiver takes it in. Feedback is the response, like a nod or a question. Noise is anything that blocks the message. A loud room is external noise. Worry is internal noise.\n\nLook at the forms. Intrapersonal is the talk you hold with yourself. Interpersonal is between two people. Small group is a team. Public speaking is one speaker to an audience. Mass communication reaches many through media. Verbal means words. Nonverbal means tone, face and posture, and the two should match.\n\nEmployers value communication, and in ministry Romans 10:14 asks, how shall they hear without a preacher?\n\nYour task is to name the parts of the process, give examples of noise and explain why words matter. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 The Communication Process and Why Speaking Matters$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Overcoming Fear and Building Confidence$j$, $j${"readings": [{"title": "Exodus 4 (King James Version)", "url": "/portal/bible/Exodus/4"}], "body": "Almost everyone feels nervous before speaking to a group. Moses felt it too. In Exodus 4:10 he said to the LORD, O my Lord, I am not eloquent, neither heretofore, nor since thou hast spoken unto thy servant: but I am slow of speech, and of a slow tongue. The LORD answered in verse 12, Now therefore go, and I will be with thy mouth, and teach thee what thou shalt say. Fear of speaking is common, and it can be managed.\n\nSpeech anxiety shows up in the body and in the mind. The body may show a fast heartbeat, shaky hands, a dry mouth or a trembling voice. These signs happen because the body releases energy to face a challenge. The mind may say, I will forget everything, or Everyone will laugh. Those thoughts are often exaggerated. Most audiences want the speaker to succeed, and listeners notice far less of your nervousness than you imagine.\n\nSeveral habits reduce fear. Preparation is the best remedy, because a speaker who knows the material has less to worry about. Practice aloud several times, and practice standing up. Breathe slowly before you begin, in through the nose for four counts and out through the mouth for six. Relax your shoulders and unclench your hands. Use positive self talk, such as I have prepared, and I have something worth saying. Picture a successful speech. Begin with a strong, memorized opening so the first moments feel steady. Look at friendly faces. Focus on helping the audience, not on how you look. Treat the extra energy as fuel and let it add life to your voice.\n\nConfidence grows with experience. Start with small steps, such as answering a question in class, then give a short talk to your family, then a longer one to a group. Keep a record of what went well and one thing to improve. Philippians 4:13 says, I can do all things through Christ which strengtheneth me. Believers do not need to rely on nerves alone. Prayer before speaking can bring peace, and trust in God steadies the heart.\n\nYour task: (1) List three physical signs of speech anxiety. (2) Describe four ways to reduce nervousness. (3) Explain how Exodus 4:10 to 12 can encourage a nervous speaker.\n\nFlorida standards: Florida speech and communication course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida speech and communication course standards", "script": "Welcome back. Listen, in Exodus 4:10 Moses said, O my Lord, I am not eloquent, but I am slow of speech, and of a slow tongue. And the LORD answered in verse 12, Now therefore go, and I will be with thy mouth, and teach thee what thou shalt say. Fear of speaking is common, and it can be managed.\n\nNow watch this. Speech anxiety shows in the body as a fast heartbeat, shaky hands, a dry mouth or a trembling voice. The body is releasing energy to face a challenge. In the mind it says, I will forget everything. Those thoughts are usually exaggerated. Most audiences want you to succeed.\n\nLook at what helps. Prepare well. Practice aloud and standing up. Breathe in for four counts and out for six. Use positive self talk. Memorize a strong opening. Look at friendly faces. Focus on helping the audience, not on how you look. Turn extra energy into life in your voice.\n\nConfidence grows with experience. Start small, then build up. Philippians 4:13 says, I can do all things through Christ which strengtheneth me. Pray before you speak and trust God to steady your heart.\n\nYour task is to list signs of anxiety, describe ways to reduce it and explain Exodus 4. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Overcoming Fear and Building Confidence$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Listening Well$j$, $j${"readings": [{"title": "James 1 (King James Version)", "url": "/portal/bible/James/1"}], "body": "Good speakers are good listeners first. James 1:19 says, Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath. Listening is not the same as hearing. Hearing is the body's ability to receive sound. Listening is the choice to pay attention and make meaning from what is said.\n\nListening has several purposes. We listen to understand information, such as a lesson or directions. We listen critically, to judge whether an argument is sound. We listen with empathy, to support a friend who is hurting. We listen for enjoyment, such as when enjoying a story or music. A wise listener knows which purpose is in play.\n\nMany things block good listening. Distractions, such as a phone, pull attention away. Prejudging a speaker before hearing the message closes the mind. Planning your reply while someone else talks means you miss what is said. Fatigue and hunger make focus harder. Because people can think about 3 or 4 times faster than they can speak, the mind has spare time and tends to wander.\n\nActive listening is a set of habits that fight these blocks. Face the speaker and give eye contact. Put away your phone. Listen for the main idea and the key supporting points. Take brief notes. Do not interrupt. Ask a question to clarify. Paraphrase, which means restating what you heard in your own words, such as, So you are saying that the deadline has moved to Friday. Watch nonverbal signals like tone and posture, which may add meaning. Respond with an open mind, even when you disagree.\n\nCritical listening asks questions. Is the speaker an expert? Is the evidence good? Does the conclusion follow from the facts? Is the speaker appealing to emotion without facts? Acts 17:11 praises the believers at Berea because they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so. They listened with respect and then tested what they heard.\n\nYour task: (1) Tell the difference between hearing and listening. (2) List four habits of active listening. (3) Paraphrase a short statement.\n\nFlorida standards: Florida speech and communication course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida speech and communication course standards", "script": "Welcome back. Listen, James 1:19 says, Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath. Good speakers are good listeners first.\n\nNow watch this. Hearing is receiving sound. Listening is choosing to pay attention and make meaning. We listen for information, to judge an argument, to support someone with empathy and for enjoyment.\n\nLook at what blocks listening. Distractions like a phone. Prejudging the speaker. Planning your reply while the speaker talks. Fatigue. And because we think three or four times faster than we speak, the mind wanders.\n\nActive listening fights these blocks. Face the speaker. Put away the phone. Listen for the main idea. Take brief notes. Do not interrupt. Ask a clarifying question. Paraphrase, which means to restate in your own words. Watch tone and posture.\n\nCritical listening asks, is the speaker an expert, is the evidence good, does the conclusion follow? Acts 17:11 says the Bereans received the word with all readiness of mind, and searched the scriptures daily, whether those things were so. They listened with respect and then tested what they heard.\n\nYour task is to tell hearing from listening, list habits and paraphrase a statement. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Listening Well$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Ethics, Honesty and Respect in Speech$j$, $j${"readings": [{"title": "Ephesians 4 (King James Version)", "url": "/portal/bible/Ephesians/4"}], "body": "A speaker holds power. An audience gives time and trust, and speakers owe them honesty and respect. Ephesians 4:29 says, Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying, that it may minister grace unto the hearers. Ephesians 4:25 adds, Wherefore putting away lying, speak every man truth with his neighbour.\n\nEthical speaking rests on a few principles. Be truthful. Do not state as fact what you know to be false, and do not leave out facts that change the meaning. Be accurate. Check your sources and correct mistakes. Be fair. Represent other views honestly and not as a weak copy that is easy to knock down. Be respectful. Avoid insults, name calling and language that attacks people for their race, background, faith, disability or appearance. Disagree with ideas without attacking persons. Be responsible. Think about the effect of your words on those who hear them.\n\nPlagiarism is presenting someone else's words or ideas as your own. It is a form of lying and a form of theft. To avoid it, give credit whenever you use another person's exact words, their ideas in your own words, or their data. In a speech, use an oral citation, such as, According to the National Weather Service in a report published in 2024. Never submit work written by another person, or by an artificial intelligence tool, as if it were fully your own. If a teacher allows the use of AI for brainstorming or editing, say so honestly, and always check facts, because AI tools can state false things with confidence.\n\nSpeakers also respect privacy and confidence. Do not share another person's private information, such as health, family trouble or messages, without permission. In ministry and school, some things told in confidence must be protected. Speakers should also respect the setting. Humor should never wound. The tone should fit the audience, and the language should be clean.\n\nFree speech allows people to say many things, but being free to say something does not make it wise or kind. Proverbs 15:1 says, A soft answer turneth away wrath: but grievous words stir up anger.\n\nYour task: (1) List four principles of ethical speaking. (2) Define plagiarism and tell how to avoid it. (3) Explain why a speaker should check facts before using them.\n\nFlorida standards: Florida speech and communication course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida speech and communication course standards", "script": "Welcome back. Listen, Ephesians 4:29 says, Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying, that it may minister grace unto the hearers. A speaker holds power, and an audience gives time and trust.\n\nNow watch this. Ethical speaking is truthful, accurate, fair, respectful and responsible. Do not state as fact what you know is false. Check your sources. Represent other views honestly. Disagree with ideas without attacking persons.\n\nLook at plagiarism. It is presenting someone else's words or ideas as your own. It is a form of lying. Give credit when you use exact words, ideas or data. In a speech say, according to the National Weather Service in a report published in 2024. Do not submit work written by someone else, or by an AI tool, as if it were fully your own. Always check facts, because AI can state false things with confidence.\n\nProtect privacy and confidences. Keep humor from wounding. Being free to say something does not make it wise. Proverbs 15:1 says, A soft answer turneth away wrath: but grievous words stir up anger.\n\nYour task is to list ethical principles, define plagiarism and explain fact checking. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Ethics, Honesty and Respect in Speech$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Foundations of Communication and Confidence$j$, $j${"prompt": "Write a report of at least 250 words on the foundations of communication. Use complete sentences and label each part. Proverbs 18:21 says, Death and life are in the power of the tongue: and they that love it shall eat the fruit thereof.\n\nPart 1: Name and define the parts of the communication process (sender, message, channel, receiver, feedback, noise and context). Give an example of each from a real conversation or speech.\nPart 2: Tell the difference between verbal and nonverbal communication, and name the five forms of communication from intrapersonal to mass communication.\nPart 3: Describe three signs of speech anxiety and five practical ways to build confidence. Explain how Exodus 4:10 to 12 can encourage a nervous speaker.\nPart 4: Explain the difference between hearing and listening, list five habits of active listening, and write a paraphrase of a sentence from a speech or sermon you have heard.\nPart 5: Describe the principles of ethical speech, define plagiarism, and explain how you will give credit and check facts in your own speeches. Apply Ephesians 4:29.", "rubric": "100 points. Part 1: 20 points. Part 2: 15 points. Part 3: 20 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Foundations of Communication and Confidence$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Words That Build Up$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time when someone's words encouraged you or hurt you, (2) explains in your own words one thing you learned about the communication process or about listening, (3) explains how a speaker can use words to build up and not tear down, and (4) connects your answer to Proverbs 18:21, James 1:19 or Ephesians 4:29. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is listening an act of love? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Words That Build Up$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: The Communication Process and Why Speaking Matters$j$, $j${"questions": [{"q": "The person who has a message to share is called the:", "options": ["Receiver", "Critic", "Channel", "Sender"]}, {"q": "A loud room that makes a speaker hard to hear is an example of:", "options": ["External noise", "Context", "Internal noise", "Feedback"]}, {"q": "A nod or a question from a listener is called:", "options": ["Feedback", "A channel", "A message", "Noise"]}, {"q": "Communication that takes place between two people is:", "options": ["Mass communication", "Intrapersonal communication", "Interpersonal communication", "Public speaking"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Communication Process and Why Speaking Matters$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,0,2}'::int[], array[$j$The sender begins the communication.$j$,$j$Noise outside the listener is external noise.$j$,$j$Feedback is the response sent back to the sender.$j$,$j$Interpersonal means between persons.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Communication Process and Why Speaking Matters$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Overcoming Fear and Building Confidence$j$, $j${"questions": [{"q": "Which is the best single remedy for speech anxiety?", "options": ["Memorizing nothing", "Speaking as fast as possible", "Avoiding all audiences", "Thorough preparation and practice"]}, {"q": "A fast heartbeat and shaky hands before a speech show that the body is:", "options": ["Ready to quit", "Failing", "Getting sick", "Releasing energy to face a challenge"]}, {"q": "Positive self talk means:", "options": ["Ignoring your preparation", "Telling yourself that you are prepared and have something worth saying", "Blaming the audience", "Telling yourself that you will fail"]}, {"q": "In Exodus 4:12 the LORD told Moses that He would:", "options": ["Be with his mouth and teach him what to say", "Remove the need to speak", "Send someone else instead", "Make him silent"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Overcoming Fear and Building Confidence$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,1,0}'::int[], array[$j$A speaker who knows the material worries less.$j$,$j$The body prepares for a challenge, and that energy can be used.$j$,$j$What you tell yourself shapes how you feel.$j$,$j$God promised to help Moses speak.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Overcoming Fear and Building Confidence$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Listening Well$j$, $j${"questions": [{"q": "Restating what a speaker said in your own words is called:", "options": ["Paraphrasing", "Prejudging", "Memorizing", "Interrupting"]}, {"q": "Listening is different from hearing because listening:", "options": ["Ignores the message", "Is a choice to pay attention and make meaning", "Requires speaking loudly", "Is only the sound reaching the ear"]}, {"q": "Which is a barrier to good listening?", "options": ["Asking a clarifying question", "Taking brief notes", "Planning your reply while the speaker is talking", "Giving eye contact"]}, {"q": "Listening to judge whether an argument is sound is called:", "options": ["Critical listening", "Listening for enjoyment", "Distracted listening", "Empathic listening"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Listening Well$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,2,0}'::int[], array[$j$Paraphrasing shows understanding and checks accuracy.$j$,$j$Hearing is automatic, while listening takes effort.$j$,$j$Planning a reply means missing what is being said.$j$,$j$Critical listening tests the speaker's evidence and logic.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Listening Well$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Ethics, Honesty and Respect in Speech$j$, $j${"questions": [{"q": "Presenting someone else's words or ideas as your own is:", "options": ["Feedback", "Paraphrasing with credit", "Plagiarism", "Research"]}, {"q": "An oral citation in a speech sounds like:", "options": ["Trust me", "According to the National Weather Service in a report published in 2024", "Everybody knows this is true", "I just made this up"]}, {"q": "Ethical speakers disagree by:", "options": ["Interrupting", "Insulting the other side", "Hiding facts", "Attacking ideas and not persons"]}, {"q": "Why should a speaker check facts produced by an AI tool?", "options": ["AI can state false things with confidence", "AI cannot write words", "AI is never wrong", "Facts never matter"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Ethics, Honesty and Respect in Speech$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,0}'::int[], array[$j$Plagiarism is dishonest because it hides the real source.$j$,$j$An oral citation names the source and date.$j$,$j$Respect means challenging ideas, not people.$j$,$j$Always verify information before sharing it.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Ethics, Honesty and Respect in Speech$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Foundations of Communication and Confidence$j$, $j${"questions": [{"q": "The way a message travels, such as a voice, a phone call or a letter, is the:", "options": ["Channel", "Context", "Feedback", "Receiver"]}, {"q": "Worry or distracting thoughts inside a listener's mind are called:", "options": ["Internal noise", "Feedback", "A channel", "External noise"]}, {"q": "A speaker says I am glad to be here in a flat voice with a frown. Listeners may doubt the words because:", "options": ["The room was too bright", "The audience was too large", "The nonverbal message does not match the verbal message", "The speaker used too many words"]}, {"q": "Which of these is a good way to calm nerves before a speech?", "options": ["Skip practice", "Breathe in for four counts and out for six", "Read faster", "Avoid looking at anyone"]}, {"q": "Most audiences, when it comes to a nervous speaker, usually:", "options": ["Notice every shaky hand", "Leave the room", "Want the speaker to succeed", "Hope the speaker fails"]}, {"q": "Active listening includes:", "options": ["Preparing your answer while the speaker talks", "Interrupting often", "Giving eye contact and asking a clarifying question", "Checking your phone"]}, {"q": "Plagiarism is wrong because it is:", "options": ["A good way to learn", "Too slow", "A form of dishonesty and theft of ideas", "Allowed with a smile"]}, {"q": "Ephesians 4:29 teaches that our words should be:", "options": ["Loud and angry", "Used to gossip", "Clever but harsh", "Good for building up and ministering grace to the hearers"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Foundations of Communication and Confidence$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,1,2,2,2,3}'::int[], array[$j$The channel carries the message.$j$,$j$Internal noise comes from within the person.$j$,$j$Mixed signals reduce trust.$j$,$j$Slow breathing relaxes the body.$j$,$j$Listeners are generally supportive.$j$,$j$These habits keep attention on the speaker.$j$,$j$Credit is owed to the original author.$j$,$j$Speech should edify others.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Foundations of Communication and Confidence$j$ on conflict (item_id) do nothing;
